'use client';
import {useCallback,useEffect,useMemo,useState} from 'react';
import StandaloneFrame from './StandaloneFrame';
import InternetWorkspace from './InternetWorkspace';

type Article={id:string;title:string;description:string;url:string;source:string;publishedAt:string;category:string};
type Section='Top stories'|'Africa'|'World'|'Business'|'Technology'|'Following'|'Saved'|'My sources';
const sections:Section[]=['Top stories','Africa','World','Business','Technology','Following','Saved','My sources'];
const storageKey='bazaara-news-personal-v4';
function stored(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'{}') as {saved?:Article[];topics?:string[]};return{saved:Array.isArray(data.saved)?data.saved.filter(x=>x&&typeof x.url==='string').slice(0,60):[],topics:Array.isArray(data.topics)?data.topics.filter(x=>typeof x==='string').slice(0,12):[]};}catch{return{saved:[] as Article[],topics:[] as string[]};}}
const TOPICS=['Africa','Technology','Business','Science','Health','World','Climate','Politics'];
export default function NewsExperience(){
 const [section,setSection]=useState<Section>('Top stories'),[data,setData]=useState<Article[]>([]),[saved,setSaved]=useState<Article[]>([]),[topics,setTopics]=useState<string[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(''),[query,setQuery]=useState(''),[updated,setUpdated]=useState(''),[hydrated,setHydrated]=useState(false);
 useEffect(()=>{const d=stored();setSaved(d.saved);setTopics(d.topics);setHydrated(true);},[]);
 useEffect(()=>{if(!hydrated)return;try{localStorage.setItem(storageKey,JSON.stringify({saved,topics}));}catch{/* private browsing */}},[saved,topics,hydrated]);
 const fetchNews=useCallback(async(category:string)=>{setLoading(true);setError('');try{const r=await fetch(`/api/headlines?category=${encodeURIComponent(category)}`,{cache:'no-store'});const j=await r.json() as {articles?:Article[];message?:string;retrievedAt?:string};if(!r.ok)throw Error(j.message||'News feeds unavailable');setData(Array.isArray(j.articles)?j.articles:[]);setUpdated(j.retrievedAt||'');}catch(e){setData([]);setError(e instanceof Error?e.message:'Could not retrieve news');}finally{setLoading(false);}},[]);
 useEffect(()=>{if(!['Saved','My sources'].includes(section))void fetchNews(section==='Following'?'top':section.toLowerCase()==='top stories'?'top':section.toLowerCase());},[section,fetchNews]);
 const visible=useMemo(()=>{const source=section==='Saved'?saved:data;const topicFilter=section==='Following'&&topics.length>0?source.filter(a=>topics.some(t=>`${a.title} ${a.description} ${a.category}`.toLowerCase().includes(t.toLowerCase()))):source;return query.trim()?topicFilter.filter(a=>`${a.title} ${a.description} ${a.source}`.toLowerCase().includes(query.trim().toLowerCase())):topicFilter;},[section,data,saved,query,topics]);
 function toggleSave(article:Article){setSaved(current=>current.some(a=>a.url===article.url)?current.filter(a=>a.url!==article.url):[article,...current].slice(0,60));}
 function toggleTopic(topic:string){setTopics(current=>current.includes(topic)?current.filter(t=>t!==topic):[...current,topic]);}
 const isLibrary=section==='My sources';
 return <StandaloneFrame product="News" tagline="Discover news from real publishers" tabs={sections} active={section} onTab={t=>{setSection(t as Section);setQuery('');}} actions={<span className="ig-muted ig-news-status">Original reporting • Real sources</span>}>
  {isLibrary?<div className="ig-legacy"><InternetWorkspace kind="news"/></div>:<>
   <div className="ig-news-heading"><div><span className="ig-news-kicker">BAZAARA / INTERNET / NEWS</span><h1 className="ig-page-title">{section==='Top stories'?'Your world, in focus.':section}</h1><p className="ig-subtitle">Headlines from connected publishers, with links to original reporting. No synthetic articles or invented scores.</p></div><div className="ig-news-search"><input aria-label="Find headlines" className="ig-field" placeholder="Search these headlines" value={query} onChange={e=>setQuery(e.target.value)}/><button type="button" className="ig-secondary" onClick={()=>void fetchNews(section==='Top stories'?'top':section==='Following'?'top':section.toLowerCase())} disabled={loading||section==='Saved'}>↻ Refresh</button></div></div>
   {section==='Following'&&<section className="ig-card ig-news-follow"><h2 className="ig-section-title">Topics you follow</h2><p className="ig-muted">Choose subjects to filter the currently connected feeds. Preferences remain in this browser.</p><div className="ig-row">{TOPICS.map(topic=><button key={topic} type="button" className="ig-pill" aria-pressed={topics.includes(topic)} onClick={()=>toggleTopic(topic)}>{topics.includes(topic)?'✓ ': '+ '}{topic}</button>)}</div>{topics.length===0&&<p className="ig-muted">Select at least one topic to create a personalized feed.</p>}</section>}
   {error&&<div className="ig-alert" role="alert">{error} — try again later. Articles are never generated when a feed is offline.</div>}
   {updated&&<p className="ig-news-updated">Updated {new Date(updated).toLocaleTimeString()} · {visible.length} {section==='Saved'?'saved stories':'available headlines'}</p>}
   {loading?<div className="ig-empty" role="status">Retrieving current headlines…</div>:visible.length===0?<div className="ig-empty"><h2>{section==='Saved'?'No saved stories':section==='Following'&&topics.length===0?'Choose topics above':'No articles available'}</h2><p>{section==='Saved'?'Save a headline from any section to find it here.':section==='Following'?'Your feed shows only matching connected-source coverage.':'Check the feed connection or change category.'}</p></div>:<div className="ig-news-layout"><div className="ig-news-feed">
    {visible.map((item,index)=><article key={`${item.id}-${index}`} className={`ig-card ig-article ${index===0?'ig-article-lead':''}`}><div className="ig-article-top"><span className="ig-news-source">{item.source}</span><time dateTime={item.publishedAt}>{item.publishedAt?new Date(item.publishedAt).toLocaleString():''}</time></div><a href={item.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer" className="ig-article-title">{item.title} ↗</a>{item.description&&<p>{item.description}</p>}<div className="ig-article-bottom"><span>{item.category}</span><div className="ig-row"><button type="button" className="ig-secondary" aria-label={saved.some(s=>s.url===item.url)?`Remove ${item.title} from saved`:`Save ${item.title}`} onClick={()=>toggleSave(item)}>{saved.some(s=>s.url===item.url)?'★ Saved':'☆ Save'}</button><button type="button" className="ig-secondary" onClick={()=>{void (navigator.share?navigator.share({title:item.title,url:item.url}):navigator.clipboard?.writeText(item.url));}}>Share ↗</button></div></div></article>)}
   </div><aside className="ig-news-aside"><div className="ig-card"><span className="ig-news-kicker">YOUR EDITION</span><h2>Follow the story, not the noise.</h2><p>Open the publisher for the complete article. Compare coverage across sources when multiple connected feeds cover the same topic.</p><div className="ig-news-divider"/><h3>Quick sections</h3>{sections.slice(1,5).map(t=><button key={t} onClick={()=>setSection(t)} className="ig-news-quick">{t} <span>→</span></button>)}</div><div className="ig-card"><h3>Saved for later</h3><strong className="ig-news-number">{saved.length}</strong><p>Your saved headlines stay in this browser. <button type="button" className="ig-news-link" onClick={()=>setSection('Saved')}>View saved →</button></p></div></aside></div>}
  </>}
 </StandaloneFrame>;
}
