'use client';
import {useEffect,useState,type ReactNode} from 'react';

type Product='Search'|'BMap'|'Translate'|'News'|'BazLens';
const APPS:{name:Product;port:number;mark:string}[]=[{name:'Search',port:3020,mark:'⌕'},{name:'BMap',port:3038,mark:'⌖'},{name:'Translate',port:3039,mark:'文'},{name:'News',port:3040,mark:'▤'},{name:'BazLens',port:3041,mark:'◎'}];
function localHref(port:number){ if(typeof window==='undefined')return '#';const h=window.location.hostname;return ['localhost','127.0.0.1','::1'].includes(h)?`${window.location.protocol}//${h.includes(':')?`[${h}]`:h}:${port}/`:'#';}
export default function StandaloneFrame({product,tagline,tabs,active,onTab,children,actions}:{product:Product;tagline:string;tabs:string[];active:string;onTab:(tab:string)=>void;children:ReactNode;actions?:ReactNode}){
 const [urls,setUrls]=useState<Record<string,string>>({});const [menu,setMenu]=useState(false);
 useEffect(()=>{const m:Record<string,string>={};for(const app of APPS)m[app.name]=localHref(app.port);m.Workspace=localHref(3021);m.Account=localHref(3004)+'account';setUrls(m);},[]);
 return <div className="ig-app"><header className="ig-header"><div className="ig-brand"><a href={urls.Workspace||'#'} aria-label="BAZAARA home" className="ig-logo">◇ <span>BAZAARA</span></a><span className="ig-brand-divider"/><strong>{product}</strong><span className="ig-tagline">{tagline}</span></div><div className="ig-top-actions">{actions}<button type="button" className="ig-icon-button" onClick={()=>setMenu(v=>!v)} aria-label="BAZAARA applications" aria-expanded={menu}>▦</button><a className="ig-avatar" href={urls.Account||'#'} aria-label="BazID account">B</a></div></header>
 {menu&&<div className="ig-app-menu" role="dialog" aria-label="BAZAARA Internet apps"><div className="ig-menu-head"><strong>BAZAARA Internet</strong><button onClick={()=>setMenu(false)} aria-label="Close">✕</button></div><div className="ig-menu-grid">{APPS.map(app=><a key={app.name} href={urls[app.name]||'#'} aria-current={app.name===product?'page':undefined}><span>{app.mark}</span>{app.name}</a>)}</div><a href={urls.Workspace||'#'} className="ig-workspace-link">All BAZAARA apps ↗</a></div>}
 <div className="ig-layout"><nav className="ig-rail" aria-label={`${product} navigation`}>
 <a className="ig-rail-home" href={urls.Workspace||'#'} title="All BAZAARA apps" aria-label="All BAZAARA apps">◇</a>
 {(product==='News'?tabs.filter(t=>['Top stories','Following','Saved','My sources'].includes(t)):tabs).map(tab=>{
 const symbols:Record<string,string>={'Top stories':'▤','Following':'☆','Saved':'▣','My sources':'◎','Text':'文','Documents':'▤','Websites':'⌕','History':'◷','Explore':'◉','Results':'▥','Saved scans':'☆'};
 return <button type="button" key={tab} onClick={()=>onTab(tab)} title={tab} aria-current={tab===active?'page':undefined}><span>{symbols[tab]||'•'}</span><small>{tab}</small></button>;
 })}</nav><div className="ig-stage"><nav className="ig-tabs" aria-label={`${product} sections`}>{tabs.map(tab=><button key={tab} type="button" aria-current={tab===active?'page':undefined} onClick={()=>onTab(tab)}>{tab}</button>)}</nav><main className="ig-content">{children}</main></div></div></div>;
}
